   489→      const categoryMap: Record<
   490→        string,
   491→        | "house"
   492→        | "flat"
   493→        | "land"
   494→        | "parking/garage/box"
   495→        | "office"
   496→        | "shop"
   497→        | "warehouse"
   498→        | "building"
   499→      > = {
   500→        house: "house",
   501→        flat: "flat",
   502→        land: "land",
   503→        parking: "parking/garage/box",
   504→      };
