   258→export async function analyzePropertyLocationAction(
   259→  input: GeolocationAnalysisInput,
   260→) {
   261→  try {
   262→    const user = await getUser();
   263→    if (!user) {
   264→      return { success: false, error: "Utilisateur non connecté" };
   265→    }
   266→
   267→    // Validation des données
   268→    const { propertyAddress, radius, placeTypes } =
   269→      GeolocationAnalysisSchema.parse(input);
   270→
   271→    logger.info("Starting property location analysis", {
   272→      userId: user.id,
   273→      address: propertyAddress,
   274→      radius,
   275→      placeTypes,
   276→    });
   277→
   278→    // Géocodage de l'adresse
   279→    const geocodingResult = await integrations.geocodeAddress(propertyAddress);
   280→
   281→    if (!geocodingResult.success || !geocodingResult.data) {
   282→      return {
   283→        success: false,
   284→        error: "Impossible de localiser l'adresse fournie",
   285→      };
   286→    }
   287→
   288→    const location = {
   289→      lat: geocodingResult.data.latitude,
   290→      lng: geocodingResult.data.longitude,
   291→    };
   292→
   293→    // Recherche de lieux à proximité
   294→    const typesToSearch = placeTypes ?? [
   295→      "school",
   296→      "hospital",
   297→      "grocery_or_supermarket",
   298→      "restaurant",
   299→      "bank",
   300→      "pharmacy",
   301→      "park",
   302→    ];
   303→
   304→    const placesPromises = typesToSearch.map(async (placeType) => {
   305→      try {
   306→        const placesResult = await integrations.findNearbyPlaces(
   307→          location,
   308→          radius,
   309→          placeType,
   310→        );
   311→        if (placesResult.success && placesResult.data) {
   312→          return {
   313→            type: placeType,
   314→            places: placesResult.data.places.slice(0, 5), // Limiter à 5 par type
   315→          };
   316→        }
   317→      } catch (error) {
   318→        logger.debug(`Failed to find places of type ${placeType}`, { error });
   319→      }
   320→      return null;
   321→    });
   322→
   323→    const placesResults = await Promise.all(placesPromises);
   324→    const nearbyPlaces = placesResults.filter((result) => result !== null);
   325→
   326→    // Calcul de distances vers des points d'intérêt importants
   327→    const importantDestinations = [
   328→      {
   329→        name: "Gare la plus proche",
   330→        address: `gare ${propertyAddress.split(",")[0]}`,
   331→      },
   332→      {
   333→        name: "Centre-ville",
   334→        address: `centre ville ${propertyAddress.split(",").pop()}`,
   335→      },
   336→    ];
   337→
   338→    const distancePromises = importantDestinations.map(async (destination) => {
   339→      try {
   340→        const distanceResult = await integrations.calculateDistance(
   341→          location,
   342→          destination.address,
   343→          "driving",
   344→        );
   345→
   346→        if (distanceResult.success && distanceResult.data) {
   347→          return {
   348→            destination: destination.name,
   349→            ...distanceResult.data,
   350→          };
   351→        }
   352→      } catch (error) {
   353→        logger.debug(`Failed to calculate distance to ${destination.name}`, {
   354→          error,
   355→        });
   356→      }
   357→      return null;
   358→    });
   359→
   360→    const distanceResults = await Promise.all(distancePromises);
   361→    const distances = distanceResults.filter((result) => result !== null);
   362→
   363→    const locationAnalysis = {
   364→      address: geocodingResult.data.formattedAddress,
   365→      coordinates: location,
   366→      nearbyPlaces,
   367→      distances,
   368→      searchRadius: radius,
   369→      analyzedAt: new Date().toISOString(),
   370→    };
   371→
   372→    logger.info("Property location analysis completed", {
   373→      userId: user.id,
   374→      placesFound: nearbyPlaces.reduce(
   375→        (acc, group) => acc + group.places.length,
   376→        0,
   377→      ),
   378→      distancesCalculated: distances.length,
   379→    });
   380→
   381→    return { success: true, data: locationAnalysis };
   382→  } catch (error) {
   383→    logger.error("Property location analysis failed", { error });
   384→
   385→    if (error instanceof z.ZodError) {
   386→      return {
   387→        success: false,
   388→        error: `Données invalides: ${error.issues.map((i) => i.message).join(", ")}`,
   389→      };
   390→    }
   391→
   392→    return {
   393→      success: false,
   394→      error: "Erreur lors de l'analyse de localisation",
   395→    };
   396→  }
   397→}
