     1→import { logger } from "@/lib/logger";
     2→import type { DVFAnalysis, DVFProperty } from "./types";
     3→
     4→/**
     5→ * Cache en mémoire pour les données DVF
     6→ * En attendant l'implémentation Redis
     7→ */
     8→class MemoryDVFCache {
     9→  private readonly cache = new Map<string, { data: unknown; expiry: number }>();
    10→  private readonly defaultTtl: number;
    11→
    12→  constructor(defaultTtlMs = 6 * 60 * 60 * 1000) {
    13→    // 6 heures par défaut
    14→    this.defaultTtl = defaultTtlMs;
    15→  }
    16→
    17→  set<T>(key: string, data: T, ttlMs?: number): void {
    18→    const expiry = Date.now() + (ttlMs ?? this.defaultTtl);
    19→    this.cache.set(key, { data, expiry });
    20→
    21→    logger.debug(
    22→      `💾 [DVF Cache] Stored key: ${key} (TTL: ${Math.round((ttlMs ?? this.defaultTtl) / 1000)}s)`,
    23→    );
    24→  }
    25→
    26→  get<T>(key: string): T | null {
    27→    const entry = this.cache.get(key);
    28→
    29→    if (!entry) {
    30→      return null;
    31→    }
    32→
    33→    if (Date.now() > entry.expiry) {
    34→      this.cache.delete(key);
    35→      logger.debug(`🗑️ [DVF Cache] Expired key removed: ${key}`);
    36→      return null;
    37→    }
    38→
    39→    logger.debug(`✅ [DVF Cache] Cache hit: ${key}`);
    40→    return entry.data as T;
    41→  }
    42→
    43→  delete(key: string): boolean {
    44→    const deleted = this.cache.delete(key);
    45→    if (deleted) {
    46→      logger.debug(`🗑️ [DVF Cache] Deleted key: ${key}`);
    47→    }
    48→    return deleted;
    49→  }
    50→
    51→  clear(): void {
    52→    const size = this.cache.size;
    53→    this.cache.clear();
    54→    logger.debug(`🧹 [DVF Cache] Cleared ${size} entries`);
    55→  }
    56→
    57→  size(): number {
    58→    return this.cache.size;
    59→  }
    60→
    61→  cleanup(): number {
    62→    const now = Date.now();
    63→    let removed = 0;
    64→
    65→    for (const [key, entry] of this.cache.entries()) {
    66→      if (now > entry.expiry) {
    67→        this.cache.delete(key);
    68→        removed++;
    69→      }
    70→    }
    71→
    72→    if (removed > 0) {
    73→      logger.debug(
    74→        `🧹 [DVF Cache] Cleanup: removed ${removed} expired entries`,
    75→      );
    76→    }
    77→
    78→    return removed;
    79→  }
    80→
    81→  generateKey(...parts: (string | number)[]): string {
    82→    return parts.map((part) => String(part)).join(":");
    83→  }
    84→}
    85→
    86→/**
    87→ * Interface pour le cache Redis (future implémentation)
    88→ */
    89→export type DVFCacheInterface = {
    90→  // Analyses DVF
    91→  setAnalysis: (
    92→    propertyId: string,
    93→    analysis: DVFAnalysis,
    94→    ttlMs?: number,
    95→  ) => Promise<void>;
    96→  getAnalysis: (propertyId: string) => Promise<DVFAnalysis | null>;
    97→
    98→  // Données brutes DVF
    99→  setComparables: (
   100→    cacheKey: string,
   101→    comparables: DVFProperty[],
   102→    ttlMs?: number,
   103→  ) => Promise<void>;
   104→  getComparables: (cacheKey: string) => Promise<DVFProperty[] | null>;
   105→
   106→  // Utilitaires
   107→  delete: (key: string) => Promise<boolean>;
   108→  clear: (pattern?: string) => Promise<void>;
   109→  exists: (key: string) => Promise<boolean>;
   110→};
   111→
   112→/**
   113→ * Implémentation en mémoire du cache DVF
   114→ */
   115→export class DVFCache implements DVFCacheInterface {
   116→  private readonly cache: MemoryDVFCache;
   117→
   118→  constructor(defaultTtlMs?: number) {
   119→    this.cache = new MemoryDVFCache(defaultTtlMs);
   120→
   121→    // Nettoyage automatique toutes les heures
   122→    setInterval(
   123→      () => {
   124→        this.cache.cleanup();
   125→      },
   126→      60 * 60 * 1000,
   127→    );
   128→  }
   129→
   130→  async setAnalysis(
   131→    propertyId: string,
   132→    analysis: DVFAnalysis,
   133→    ttlMs?: number,
   134→  ): Promise<void> {
   135→    const key = this.generateAnalysisKey(propertyId);
   136→    this.cache.set(key, analysis, ttlMs);
   137→  }
   138→
   139→  async getAnalysis(propertyId: string): Promise<DVFAnalysis | null> {
   140→    const key = this.generateAnalysisKey(propertyId);
   141→    return this.cache.get<DVFAnalysis>(key);
   142→  }
   143→
   144→  async setComparables(
   145→    cacheKey: string,
   146→    comparables: DVFProperty[],
   147→    ttlMs?: number,
   148→  ): Promise<void> {
   149→    const key = this.generateComparablesKey(cacheKey);
   150→    this.cache.set(key, comparables, ttlMs);
   151→  }
   152→
   153→  async getComparables(cacheKey: string): Promise<DVFProperty[] | null> {
   154→    const key = this.generateComparablesKey(cacheKey);
   155→    return this.cache.get<DVFProperty[]>(key);
   156→  }
   157→
   158→  async delete(key: string): Promise<boolean> {
   159→    return this.cache.delete(key);
   160→  }
   161→
   162→  async clear(pattern?: string): Promise<void> {
   163→    if (pattern) {
   164→      // Pour une vraie implémentation Redis, on utiliserait SCAN avec pattern
   165→      // Ici on simule en supprimant toutes les clés pour simplifier
   166→      logger.warn(
   167→        "⚠️ [DVF Cache] Pattern clear not fully implemented in memory cache",
   168→      );
   169→    }
   170→    this.cache.clear();
   171→  }
   172→
   173→  async exists(key: string): Promise<boolean> {
   174→    return this.cache.get(key) !== null;
