   338→  /**
   339→   * Analyse un DPE existant
   340→   */
   341→  private async analyzeDPE(dpe: DPE): Promise<DPEAnalysis> {
   342→    try {
   343→      // Calculer les coûts énergétiques
   344→      const energyCost = calculateEnergyCost(
   345→        dpe.energyConsumption.value,
   346→        dpe.mainEnergyType as "electricity" | "gas" | "fuel_oil" | "wood" | "network" | "other",
   347→        dpe.surface
   348→      );
   349→      
   350→      // Évaluer les risques et recommandations
   351→      const rentalRisk = assessRentalRestrictionRisk(
   352→        dpe.energyConsumption.class,
   353→        dpe.gesEmission.class
   354→      );
   355→      
   356→      const recommendations = generateRenovationRecommendations(dpe);
   357→      const renovationCost = estimateRenovationCost(recommendations);
   358→      
   359→      // Calculer les scores
   360→      const performanceScore = calculatePerformanceScore(dpe);
   361→      const efficiencyRating = assessEnergyEfficiencyRating(performanceScore);
   362→      const environmentalRating = assessEnvironmentalImpactRating(dpe.gesEmission.class);
   363→      
   364→      // Déterminer la priorité de rénovation
   365→      const renovationPriority = this.calculateRenovationPriority(
   366→        rentalRisk,
   367→        performanceScore
   368→      );
   369→      
   370→      return {
   371→        dpe,
   372→        analysisDate: new Date().toISOString(),
   373→        confidenceLevel: dpe.dataSource === "mock" ? "medium" : "high",
   374→        
   375→        // Coûts
   376→        estimatedAnnualCost: energyCost.annualAmount,
   377→        estimatedMonthlyCost: energyCost.monthlyAmount,
   378→        costComparisonToAverage: this.calculateCostComparison(dpe.energyConsumption.class),
   379→        
   380→        // Conformité réglementaire
   381→        rentalRestrictionRisk: rentalRisk,
   382→        renovationRequired: rentalRisk === "high" || rentalRisk === "critical",
   383→        renovationPriority,
   384→        estimatedRenovationCost: renovationCost,
   385→        
   386→        // Performance
   387→        performanceScore,
   388→        energyEfficiencyRating: efficiencyRating,
   389→        environmentalImpactRating: environmentalRating,
   390→        
   391→        // Recommandations
   392→        recommendations,
   393→        
   394→        // Données sources
   395→        dataSource: dpe.dataSource,
   396→      };
   397→    } catch (error) {
   398→      if (error instanceof DPEServiceError) {
   399→        throw error;
   400→      }
   401→      throw new DPEServiceError(
   402→        `Erreur lors de l'analyse DPE: ${error instanceof Error ? error.message : 'Erreur inconnue'}`,
   403→        "API_ERROR",
   404→        error
   405→      );
   406→    }
   407→  }
   408→
   409→  /**
   410→   * Calcule la comparaison de coût par rapport à la moyenne
   411→   */
   412→  private calculateCostComparison(energyClass: EnergyClass): number {
   413→    // Valeurs moyennes nationales par classe (en €/an pour 100m²)
   414→    const averageCosts = {
   415→      A: 600,
   416→      B: 1000,
   417→      C: 1500,
   418→      D: 2100,
   419→      E: 2900,
   420→      F: 3800,
   421→      G: 4800,
   422→    };
   423→    
   424→    const currentCost = averageCosts[energyClass];
   425→    const nationalAverage = 2200; // Moyenne nationale actuelle
   426→    
   427→    return Math.round(((currentCost - nationalAverage) / nationalAverage) * 100);
   428→  }
   429→
   430→  /**
   431→   * Calcule la priorité de rénovation
   432→   */
   433→  private calculateRenovationPriority(
   434→    rentalRestrictionRisk: "low" | "medium" | "high" | "critical",
   435→    performanceScore: number
   436→  ): "low" | "medium" | "high" {
   437→    if (rentalRestrictionRisk === "critical" || rentalRestrictionRisk === "high") {
   438→      return "high";
   439→    }
   440→    
   441→    if (performanceScore < 30 || rentalRestrictionRisk === "medium") {
   442→      return "medium";
   443→    }
   444→    
   445→    return "low";
   446→  }
   447→
   448→  /**
   449→   * Calcule le niveau de confiance de l'analyse
   450→   */
   451→  private calculateConfidenceLevel(dpe: DPE): "low" | "medium" | "high" {
   452→    // Haute confiance si données récentes et complètes
   453→    if (dpe.dataSource === "api" && dpe.insulation && dpe.equipment) {
   454→      return "high";
   455→    }
   456→    
   457→    // Moyenne confiance si données partielles
   458→    if (dpe.dataSource === "api" || dpe.dataSource === "mock") {
   459→      return "medium";
   460→    }
   461→    
   462→    // Faible confiance pour les données estimées
   463→    return "low";
   464→  }
   465→
   466→  /**
   467→   * Génère une clé de cache
   468→   */
   469→  private getCacheKey(prefix: string, data: unknown): string {
   470→    const dataString = JSON.stringify(data);
   471→    return `${prefix}_${dataString}`;
   472→  }
   473→}
