    16→export async function analyzeDVFAction(
    17→  property: Property,
    18→): Promise<DVFAnalysisResult> {
    19→  try {
    20→    logger.debug("🔍 [DVFAction] Début analyse DVF", {
    21→      propertyId: property.id,
    22→      city: property.city,
    23→      price: property.price,
    24→    });
    25→
    26→    // Vérifications des données minimales requises
    27→    if (!property.coordinates) {
    28→      return {
    29→        analysis: null,
    30→        error: "Coordonnées géographiques manquantes pour l'analyse DVF",
    31→      };
    32→    }
    33→
    34→    if (!property.surface || property.surface <= 0) {
    35→      return {
    36→        analysis: null,
    37→        error: "Surface du bien manquante pour l'analyse DVF",
    38→      };
    39→    }
    40→
    41→    if (!property.price || property.price <= 0) {
    42→      return {
    43→        analysis: null,
    44→        error: "Prix du bien manquant pour l'analyse DVF",
    45→      };
    46→    }
    47→
    48→    // Analyse DVF
    49→    const analysis = await dvfService.analyzeProperty(property);
    50→
    51→    logger.debug("✅ [DVFAction] Analyse DVF terminée", {
    52→      propertyId: property.id,
    53→      overpricingPercent: analysis.overpricingPercent,
    54→      comparableCount: analysis.comparableCount,
    55→      confidenceLevel: analysis.confidenceLevel,
    56→    });
    57→
    58→    return {
    59→      analysis,
    60→      error: null,
    61→    };
    62→  } catch (error) {
    63→    logger.error("❌ [DVFAction] Erreur analyse DVF:", {
    64→      propertyId: property.id,
    65→      error: error instanceof Error ? error.message : "Erreur inconnue",
    66→    });
    67→
    68→    // Messages d'erreur user-friendly
    69→    let userError = "Impossible d'analyser le marché local pour ce bien";
