    73→        userError = "Aucune transaction comparable trouvée dans cette zone";
    74→      } else if (error.message.includes("API")) {
    75→        userError = "Service d'analyse temporairement indisponible";
    76→      } else if (error.message.includes("coordonnées")) {
    77→        userError = "Localisation du bien insuffisamment précise";
    78→      }
    79→    }
    80→
    81→    return {
    82→      analysis: null,
    83→      error: userError,
    84→    };
    85→  }
    86→}
