     6→
     7→type EmailParams = {
     8→  from: string;
     9→  to: string | string[];
    10→  subject: string;
    11→
    12→  text?: string;
    13→  replyTo?: string;
    14→  cc?: string | string[];
    15→  bcc?: string | string[];
    16→  attachments?: Attachment[];
    17→  html: string;
    18→};
    19→
    20→type Attachment = {
    21→  content?: string | Buffer;
    22→  filename?: string | false | undefined;
    23→  path?: string;
    24→  contentType?: string;
    25→};
    26→
    27→export type MailAdapter = {
    28→  send: (params: EmailParams) => Promise<
    29→    | {
    30→        error: null;
    31→        data: {
    32→          id: string;
    33→        };
    34→      }
    35→    | {
    36→        error: Error;
    37→        data: null;
    38→      }
    39→  >;
    40→};
    41→
    42→/**
    43→ * sendEmail will send an email using resend.
    44→ * To avoid repeating the same "from" email, you can leave it empty and it will use the default one.
    45→ * Also, in development, it will add "[DEV]" to the subject.
    46→ * @param params[0] : payload
    47→ * @param params[1] : options
    48→ * @returns a promise of the email sent
    49→ */
    50→
    51→// If you use another mail adapter, you can replace the mailAdapter with your own
    52→const mailAdapter: MailAdapter = resendMailAdapter;
    53→
    54→type SendEmailParams = Omit<EmailParams, "from" | "html"> & {
    55→  from?: string;
    56→  html?: string | React.ReactElement;
    57→};
    58→
    59→export const sendEmail = async (params: SendEmailParams) => {
    60→  if (env.NODE_ENV === "development") {
    61→    params.subject = `[DEV] ${params.subject}`;
    62→  }
    63→
    64→  // Avoid sending emails to playwright-test emails
    65→  if (
    66→    Array.isArray(params.to)
    67→      ? params.to.some((to) => to.startsWith("playwright-test-"))
    68→      : params.to.startsWith("playwright-test-")
    69→  ) {
    70→    logger.info("[sendEmail] Sending email to playwright-test", {
    71→      subject: params.subject,
    72→      to: params.to,
    73→    });
    74→
    75→    return {
    76→      error: null,
    77→      data: {
    78→        id: nanoid(),
    79→      },
    80→    };
    81→  }
    82→
    83→  let html = "";
    84→
    85→  if (typeof params.html === "string") {
    86→    html = params.html;
    87→  } else {
    88→    html = await pretty(await render(params.html));
    89→  }
    90→
    91→  const result = await mailAdapter.send({
    92→    ...params,
    93→    from: params.from ?? env.EMAIL_FROM,
    94→    html,
    95→  });
    96→
    97→  if (result.error) {
    98→    logger.error("[sendEmail] Error", { result, subject: params.subject });
    99→  }
   100→
   101→  return result;
   102→};
