    22→      b2bPermission: B2BPermission;
    23→    }
    24→  | {
    25→      b2cPermission: B2CPermission;
    26→      b2bPermission: B2BPermission;
    27→    }
    28→);
    29→
    30→/**
    31→ * Permission Guard Component
    32→ * Protects content based on B2C or B2B permissions
    33→ */
    34→export async function PermissionGuard({
    35→  children,
    36→  fallback = null,
    37→  redirectTo,
    38→  b2cPermission,
    39→  b2bPermission,
    40→}: PermissionGuardProps) {
    41→  const userContext = await getUserContext();
    42→
    43→  if (!userContext) {
    44→    if (redirectTo) {
    45→      redirect("/auth/signin");
    46→    }
    47→    return <>{fallback}</>;
    48→  }
    49→
    50→  let hasPermission = false;
    51→
    52→  // Check B2C permissions for individuals
    53→  if (userContext.accountType === "individual" && b2cPermission) {
    54→    hasPermission = await hasB2CPermissionAsync(b2cPermission);
    55→  }
    56→
    57→  // Check B2B permissions for professionals
    58→  if (userContext.accountType === "professional" && b2bPermission) {
    59→    hasPermission = await hasB2BPermissionAsync(b2bPermission);
    60→  }
    61→
    62→  if (!hasPermission) {
    63→    if (redirectTo) {
    64→      redirect(redirectTo);
    65→    }
    66→    return <>{fallback}</>;
    67→  }
    68→
    69→  return <>{children}</>;
    70→}
    71→
    72→type AccountTypeGuardProps = {
    73→  children: ReactNode;
    74→  accountType: "individual" | "professional";
    75→  fallback?: ReactNode;
    76→  redirectTo?: string;
    77→};
    78→
    79→/**
    80→ * Account Type Guard Component
    81→ * Protects content based on account type (B2C vs B2B)
    82→ */
    83→export async function AccountTypeGuard({
    84→  children,
    85→  accountType,
    86→  fallback = null,
    87→  redirectTo,
    88→}: AccountTypeGuardProps) {
    89→  const userContext = await getUserContext();
    90→
    91→  if (!userContext) {
    92→    if (redirectTo) {
    93→      redirect("/auth/signin");
    94→    }
    95→    return <>{fallback}</>;
    96→  }
    97→
    98→  if (userContext.accountType !== accountType) {
    99→    if (redirectTo) {
   100→      const defaultRedirect =
   101→        accountType === "individual" ? "/dashboard" : "/orgs";
   102→      redirect(redirectTo || defaultRedirect);
   103→    }
   104→    return <>{fallback}</>;
   105→  }
   106→
   107→  return <>{children}</>;
   108→}
   109→
   110→type RoleGuardProps = {
   111→  children: ReactNode;
   112→  roles: string[];
   113→  fallback?: ReactNode;
   114→  redirectTo?: string;
   115→};
   116→
   117→/**
   118→ * Role Guard Component
   119→ * Protects content based on specific roles
   120→ */
   121→export async function RoleGuard({
   122→  children,
   123→  roles,
   124→  fallback = null,
   125→  redirectTo,
   126→}: RoleGuardProps) {
   127→  const userContext = await getUserContext();
   128→
   129→  if (!userContext) {
   130→    if (redirectTo) {
   131→      redirect("/auth/signin");
   132→    }
   133→    return <>{fallback}</>;
   134→  }
   135→
   136→  // For professionals, check organization role
   137→  if (userContext.accountType === "professional") {
   138→    const hasRole =
   139→      userContext.organizationRole &&
   140→      roles.includes(userContext.organizationRole);
   141→
   142→    if (!hasRole) {
   143→      if (redirectTo) {
   144→        redirect(redirectTo);
   145→      }
   146→      return <>{fallback}</>;
   147→    }
   148→  }
   149→
   150→  // For individuals, only check if they have the "individualBuyer" role
   151→  if (userContext.accountType === "individual") {
   152→    const hasRole = roles.includes("individualBuyer");
   153→
   154→    if (!hasRole) {
   155→      if (redirectTo) {
   156→        redirect(redirectTo);
   157→      }
   158→      return <>{fallback}</>;
   159→    }
   160→  }
   161→
   162→  return <>{children}</>;
   163→}
