    12→export class MoteurImmoPremiumService extends BaseIntegration {
    13→  constructor() {
    14→    super("moteurimmo-premium", getIntegrationConfig("moteurimmo-premium"));
    15→  }
    16→
    17→  /**
    18→   * Récupération enrichie d'un bien avec données premium
    19→   */
    20→  async getEnrichedProperty(
    21→    propertyId: string,
    22→  ): Promise<IntegrationResponse<EnrichedProperty>> {
    23→    return this.execute(async () => {
    24→      // Récupération de base via le client existant
    25→      const baseProperty = await (moteurImmoClient as any).getProperty(
    26→        propertyId,
    27→      );
    28→
    29→      if (!baseProperty.success || !baseProperty.data) {
    30→        throw new Error(`Property ${propertyId} not found`);
    31→      }
    32→
    33→      // Enrichissement avec données premium
    34→      const enrichedData = await this.enrichPropertyData(baseProperty.data);
    35→
    36→      return {
    37→        ...baseProperty.data,
    38→        ...enrichedData,
    39→        enrichmentTimestamp: Date.now(),
    40→      };
    41→    }, "getEnrichedProperty");
    42→  }
    43→
    44→  /**
    45→   * Surveillance des baisses de prix sur une liste de biens
    46→   */
    47→  async monitorPriceDrops(
    48→    propertyIds: string[],
    49→  ): Promise<IntegrationResponse<PriceDropAlert[]>> {
    50→    return this.execute(async () => {
    51→      const propertyPromises = propertyIds.map(async (propertyId) => {
    52→        try {
    53→          const [currentProperty, priceHistory] = await Promise.all([
    54→            (moteurImmoClient as any).getProperty(propertyId),
    55→            this.getPriceHistory(propertyId),
    56→          ]);
    57→
    58→          if (currentProperty.success && currentProperty.data) {
    59→            const currentPrice = currentProperty.data.price;
    60→
    61→            if (priceHistory.length > 0) {
    62→              const lastPrice = priceHistory[priceHistory.length - 1].price;
    63→
    64→              if (currentPrice < lastPrice) {
    65→                const dropAmount = lastPrice - currentPrice;
    66→                const dropPercentage = (dropAmount / lastPrice) * 100;
    67→
    68→                await this.savePriceHistory(propertyId, currentPrice);
    69→
    70→                return {
    71→                  propertyId,
    72→                  property: currentProperty.data,
    73→                  previousPrice: lastPrice,
    74→                  newPrice: currentPrice,
    75→                  dropAmount,
    76→                  dropPercentage: Number(dropPercentage.toFixed(2)),
    77→                  detectedAt: new Date(),
    78→                };
    79→              }
    80→            }
    81→
    82→            // Sauvegarder le prix actuel même s'il n'y a pas de baisse
    83→            await this.savePriceHistory(propertyId, currentPrice);
    84→          }
    85→        } catch (error) {
    86→          console.debug(
    87→            `Failed to monitor price for property ${propertyId}:`,
    88→            error,
    89→          );
    90→        }
    91→        return null;
    92→      });
    93→
    94→      const results = await Promise.all(propertyPromises);
    95→      const alerts = results.filter(
    96→        (alert): alert is PriceDropAlert => alert !== null,
    97→      );
    98→
    99→      return alerts;
   100→    }, "monitorPriceDrops");

